Method.Source:
/// <summary>
/// N.Freidenberger 04.02.2025
/// </summary>
public void postBuild()
{
    super();

    dlgEcoResProductNum = this.bindInfo().getDialogField(this.dataContractObject(),methodStr(AVAReassignItemToNewProductContract,parmNewProduct));
    dlgEcoResProductNum.registerOverrideMethod(methodStr(FormStringControl,lookup),methodStr(AVAReassignItemToProductUIBuider,lookupEcoResProductNum),this);
}

/// <summary>
/// N.Freidenberger 04.02.2025
/// </summary>
/// <param name = "_formStringControl">_formStringControl</param>
private void lookupEcoResProductNum(FormStringControl       _formStringControl)  
{
    Query               query = new Query();
    SysTableLookup      sysTableLookup;

    sysTableLookup = SysTableLookup::newParameters(tableNum(EcoResProduct),_formStringControl);

    query.addDataSource(tableNum(EcoResProduct));

    sysTableLookup.addLookupfield(fieldNum(EcoResProduct,DisplayProductNumber),true);
    sysTableLookup.addLookupfield(fieldNum(EcoResProduct,ProductType));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();

}
